import { DesktopBackBar } from "./components/DesktopBackBar";
import { Toaster } from "@/components/ui/toaster";
import { Toaster as Sonner } from "@/components/ui/sonner";
import { TooltipProvider } from "@/components/ui/tooltip";
import SEO from "@/components/SEO";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { BrowserRouter, Navigate, Routes, Route } from "react-router-dom";
import { lazy, Suspense } from "react";
import { LanguageProvider, URL_LANGUAGES } from "@/contexts/LanguageContext";
import Index from "./pages/Index";
import SiteAnalytics from "./components/SiteAnalytics";

const queryClient = new QueryClient();
const NicsTraderApp = lazy(() => import("./pages/NicsTraderApp"));
const About = lazy(() => import("./pages/About"));
const Estate = lazy(() => import("./pages/Estate"));
const Trading = lazy(() => import("./pages/Trading"));
const NicsEcosystem = lazy(() => import("./pages/NicsEcosystem"));
const NicsMultimedia = lazy(() => import("./pages/NicsMultimedia"));
const NicsForge = lazy(() => import("./pages/NicsForge"));
const NicsVideo = lazy(() => import("./pages/NicsVideo"));
const NicsStudio = lazy(() => import("./pages/NicsStudio"));
const NicsWindowsApp = lazy(() => import("./pages/NicsWindowsApp"));
const NicsTradingSoftware = lazy(() => import("./pages/NicsTradingSoftware"));
const TelegramOnly = lazy(() => import("./components/TelegramOnly"));
const Go = lazy(() => import("./pages/Go"));
const Subtitles = lazy(() => import("./pages/Subtitles"));
const Trial = lazy(() => import("./pages/Trial"));
const Terms = lazy(() => import("./pages/Terms"));
const Privacy = lazy(() => import("./pages/Privacy"));
const DataDeletion = lazy(() => import("./pages/DataDeletion"));
const NotFound = lazy(() => import("./pages/NotFound"));
const CabinetLogin = lazy(() => import("./pages/cabinet/CabinetLogin"));
const CabinetLayout = lazy(() => import("./pages/cabinet/CabinetLayout"));
const CabinetHome = lazy(() => import("./pages/cabinet/CabinetHome"));
const CabinetAcademy = lazy(() => import("./pages/cabinet/CabinetAcademy"));
const CabinetLessonView = lazy(() => import("./pages/cabinet/CabinetLessonView"));
const CabinetAchievements = lazy(() => import("./pages/cabinet/CabinetAchievements"));
const CabinetCourses = lazy(() => import("./pages/cabinet/CabinetCourses"));
const CabinetSubscription = lazy(() => import("./pages/cabinet/CabinetSubscription"));
const CabinetServices = lazy(() => import("./pages/cabinet/CabinetServices"));
const CabinetSupport = lazy(() => import("./pages/cabinet/CabinetSupport"));
const CabinetJournal = lazy(() => import("./pages/cabinet/CabinetJournal"));
const CabinetPro = lazy(() => import("./pages/cabinet/CabinetPro"));
const CabinetTrader = lazy(() => import("./pages/cabinet/CabinetTrader"));
const CabinetAccount = lazy(() => import("./pages/cabinet/CabinetAccount"));
const CabinetLicense = lazy(() => import("./pages/cabinet/CabinetLicense"));

const App = () => (
  <QueryClientProvider client={queryClient}>
    <LanguageProvider>
      <TooltipProvider>
        <Toaster />
        <Sonner />
        <BrowserRouter>
          <Suspense fallback={<div className="min-h-screen bg-background" />}>
          <SiteAnalytics />
          <DesktopBackBar />
          <Routes>
            <Route path="/" element={<Index />} />
            {/* Crawlable localized entry points for every non-English
                language — translated meta (title/description) and
                hreflang wiring, see src/contexts/LanguageContext.tsx's
                URL_LANGUAGES and getLocalizedSeoMeta(), and
                scripts/generate-seo-pages.mjs (which derives its own
                route list from the same language set, so the two can't
                drift apart). Index, Trading, NICS Video and NICS Studio are fully translated via
                t() for every one of these languages, so these are
                genuine localized content pages, not just a translated
                meta tag over English copy. NICS Video and NICS Studio
                are translated the same way (src/i18n/nicsVideo*). */}
            {URL_LANGUAGES.map((lang) => (
              <Route key={lang} path={`/${lang}`} element={<Index />} />
            ))}
            {URL_LANGUAGES.map((lang) => (
              <Route key={`${lang}-trading`} path={`/${lang}/trading`} element={<Trading />} />
            ))}
            {URL_LANGUAGES.map((lang) => (
              <Route key={`${lang}-nics-video`} path={`/${lang}/nics-video`} element={<NicsVideo />} />
            ))}
            {URL_LANGUAGES.map((lang) => (
              <Route key={`${lang}-nics-studio`} path={`/${lang}/nics-studio`} element={<NicsStudio />} />
            ))}
            {/* Link-in-bio page for social profiles (noindex), see src/pages/Go.tsx. */}
            <Route path="/go" element={<Go />} />
            <Route path="/ru/go" element={<Go />} />
            <Route path="/bg/go" element={<Go />} />
            {/* Free subtitles tool, the NICS Video lead magnet (en, ru, bg). */}
            <Route path="/subtitles" element={<Subtitles />} />
            <Route path="/ru/subtitles" element={<Subtitles />} />
            <Route path="/bg/subtitles" element={<Subtitles />} />
            {/* NICS Trading Ecosystem card trial checkout (1.99 EUR / 7 days, then 19.99 EUR/month), linked from the bot; noindex. */}
            <Route path="/trial" element={<Trial />} />
            <Route path="/about" element={<About />} />
            <Route path="/estate" element={<Estate />} />
            <Route path="/trading" element={<Trading />} />
            <Route
              path="/nics-app"
              element={
                <>
                  <SEO
                    title="NICS Trading Ecosystem Mini App"
                    description="Authenticated NICS Trading Ecosystem user application."
                    canonical="https://aibyteconsult.com/nics-app"
                    noindex
                  />
                  <Suspense
                    fallback={
                      <main className="grid min-h-screen place-items-center bg-[#07090f] text-sm text-slate-400">
                        NICS Trading Ecosystem…
                      </main>
                    }
                  >
                    <TelegramOnly>
                      <NicsTraderApp />
                    </TelegramOnly>
                  </Suspense>
                </>
              }
            />
            <Route path="/nics-ecosystem" element={<NicsEcosystem />} />
            <Route path="/nics-multimedia" element={<NicsMultimedia />} />
            <Route path="/nics-forge" element={<NicsForge />} />
            <Route path="/nics-video" element={<NicsVideo />} />
            <Route path="/nics-studio" element={<NicsStudio />} />
            {/* Windows app page: EN + phased SEO languages (src/i18n/windowsApp.ts WINDOWS_APP_LANGS). */}
            <Route path="/nics-windows-app" element={<NicsWindowsApp />} />
            {["ru", "bg", "de", "es"].map((lang) => (
              <Route key={`${lang}-win`} path={`/${lang}/nics-windows-app`} element={<NicsWindowsApp />} />
            ))}
            {/* Level-A SEO pages in phase 1 languages (src/i18n/phasedSeo.ts PHASE1_LANGS). */}
            <Route path="/nics-trading-software" element={<NicsTradingSoftware />} />
            {["ru", "bg", "de", "es"].map((lang) => [
              <Route key={`${lang}-software`} path={`/${lang}/nics-trading-software`} element={<NicsTradingSoftware />} />,
              <Route key={`${lang}-ecosystem`} path={`/${lang}/nics-ecosystem`} element={<NicsEcosystem />} />,
              <Route key={`${lang}-about`} path={`/${lang}/about`} element={<About />} />,
            ])}
            <Route
              path="/cabinet/login"
              element={
                <Suspense fallback={<div className="min-h-screen bg-[#07090f]" />}>
                  <CabinetLogin />
                </Suspense>
              }
            />
            <Route
              path="/cabinet"
              element={
                <Suspense fallback={<div className="min-h-screen bg-[#07090f]" />}>
                  <CabinetLayout />
                </Suspense>
              }
            >
              <Route index element={<Navigate to="trader" replace />} />
              <Route path="trader/:screen?" element={<CabinetTrader />} />
              <Route path="overview" element={<CabinetHome />} />
              <Route path="account" element={<CabinetAccount />} />
              <Route path="academy" element={<CabinetAcademy />} />
              <Route path="academy/:lessonId" element={<CabinetLessonView />} />
              <Route path="achievements" element={<CabinetAchievements />} />
              <Route path="courses" element={<CabinetCourses />} />
              <Route path="subscription" element={<CabinetSubscription />} />
              <Route path="services" element={<CabinetServices />} />
              <Route path="support" element={<CabinetSupport />} />
              <Route path="journal" element={<CabinetJournal />} />
              <Route path="pro" element={<CabinetPro />} />
              <Route path="license" element={<CabinetLicense />} />
            </Route>
            <Route path="/terms" element={<Terms />} />
            <Route path="/privacy" element={<Privacy />} />
            <Route path="/delete" element={<DataDeletion />} />
            <Route path="*" element={<NotFound />} />
          </Routes>
          </Suspense>
        </BrowserRouter>
      </TooltipProvider>
    </LanguageProvider>
  </QueryClientProvider>
);

export default App;
